from taf.internal.entrypoint import EntryLookup, EntryPoint


class ChannelEmulatorEntryLookup(EntryLookup):

    @classmethod
    def in_opr(cls, entries, entry_name):
        """

        lookup class based on `in` operator in dict
        :param dict entries:
                {entry name: class}
        :param str entry_name:
                entry name
        :exception: LookupEntryFail when entry name cannot be found
        :return: True when the entry name is matched
        """
        entry_name_upper = entry_name.upper()
        entry_name_lower = entry_name.lower()
        if entry_name_upper in entries:
            entry_name = entry_name_upper
        if entry_name_lower in entries:
            entry_name = entry_name_lower
        return super(ChannelEmulatorEntryLookup, cls).in_opr(entries, entry_name)


class ChannelEmulatorFactory(object):

    def __init__(self):
        self._entry_point = EntryPoint(factory_group_name='EmulatorChannelFactory')

    def create(self, vendor, model=None, version=None, **kwargs):
        factory = self._entry_point.create_factory_instance(entry_name=vendor, lookup=ChannelEmulatorEntryLookup.in_opr)

        kwargs['vendor'] = vendor
        kwargs['model'] = model
        kwargs['version'] = version
        return factory.create(**kwargs)
